function validate([nums1, nums2]) {
  for (const [name, nums] of [['nums1', nums1], ['nums2', nums2]]) {
    if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return name + ' needs 1 to 10^5 values.';
    if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000000)) return 'Each value of ' + name + ' is an integer from 0 to 10^6.';
  }
  return null;
}

