function minSum(nums1, nums2) {
  let sum1 = 0;
  let zeros1 = 0;
  for (const value of nums1) {
    sum1 += value;
    if (value === 0) zeros1++;
  }
  let sum2 = 0;
  let zeros2 = 0;
  for (const value of nums2) {
    sum2 += value;
    if (value === 0) zeros2++;
  }
  const least1 = sum1 + zeros1;
  const least2 = sum2 + zeros2;
  if (least1 < least2 && zeros1 === 0) {
    return -1;
  }
  if (least2 < least1 && zeros2 === 0) {
    return -1;
  }
  return Math.max(least1, least2);
}

