function minSum(nums1, nums2) {
  const fits = (nums, total) => {
    let fixed = 0, blanks = 0;
    for (const v of nums) { if (v === 0) blanks++; else fixed += v; }
    return blanks === 0 ? fixed === total : fixed + blanks <= total;
  };
  const limit = [...nums1, ...nums2].reduce((a, b) => a + b, 0) + nums1.length + nums2.length;
  for (let total = 1; total <= limit; total++) if (fits(nums1, total) && fits(nums2, total)) return total;
  return -1;
}

