function generate(rand, size) {
  const rates = [0, 0, 0.2, 0.5, 1];
  const make = (n, top, rate) => Array.from({ length: n }, () => rand() < rate ? 0 : 1 + Math.floor(rand() * top));
  if (size === 'large') {
    const n1 = 1000 + Math.floor(rand() * 1001);
    const n2 = 1000 + Math.floor(rand() * 1001);
    return [make(n1, 1000000, rates[Math.floor(rand() * 4)]), make(n2, 1000000, rates[Math.floor(rand() * 4)])];
  }
  const n1 = 1 + Math.floor(rand() * 6);
  const n2 = 1 + Math.floor(rand() * 6);
  return [make(n1, 9, rates[Math.floor(rand() * rates.length)]), make(n2, 9, rates[Math.floor(rand() * rates.length)])];
}
